{* Code generated by packages/kit-compose/src/server-organisms.ts from packages/compose-gen/specs (compose-gen organism emitters on kit-compose). DO NOT EDIT.
    Source: packages/compose-gen/specs/organisms/faq-cards.json
    The questions of FaqSplit as cards: the topic, the question, the answer and a read-more link; with an icon square on top in the icons shape. Shapes: grid3, grid4, icons (three columns).
    Props (p): items, labels, cards. *}
{var $v_items = ($p['items'] ?? null)}
{var $v_labels = ($p['labels'] ?? null)}
{var $v_cards = ($p['cards'] ?? 'grid3')}
{capture $c_9}
  {foreach og_l($v_items) as $v_q}
    {capture $c_8}
      {if og_t(og_eq($v_cards, 'icons'))}
        {capture $c_1}
          {=og_include('icons/LucideIcon.latte', ['name' => og_s(og_get($v_q, ['icon'])), 'size' => 20])|noescape}
        {/capture}
        {=og_include('compose/Box.latte', ['class' => 'flex size-10 shrink-0 items-center justify-center rounded bg-muted', 'children' => (string) $c_1])|noescape}
      {/if}
      {capture $c_5}
        {capture $c_2}
          {=og_text(og_get($v_q, ['category']))}
        {/capture}
        {=og_include('compose/Badge.latte', ['variant' => 'secondary', 'size' => 'sm', 'class' => 'w-fit', 'children' => (string) $c_2])|noescape}
        {capture $c_3}
          {=og_text(og_get($v_q, ['question']))}
        {/capture}
        {=og_include('compose/Title.latte', ['as' => 3, 'size' => 'base', 'weight' => 'semibold', 'children' => (string) $c_3])|noescape}
        {capture $c_4}
          {=og_text(og_get($v_q, ['answer']))}
        {/capture}
        {=og_include('compose/Text.latte', ['size' => 'sm', 'class' => 'text-muted-foreground', 'children' => (string) $c_4])|noescape}
      {/capture}
      {=og_include('compose/Stack.latte', ['gap' => '2', 'children' => (string) $c_5])|noescape}
      {capture $c_7}
        {capture $c_6}
          {=og_text(og_get($v_labels, ['more']))}
          {=og_include('icons/LucideIcon.latte', ['name' => 'arrow-right', 'size' => 16])|noescape}
        {/capture}
        {=og_include('compose/Button.latte', ['variant' => 'link', 'size' => 'sm', 'class' => 'gap-2 px-0 font-medium', 'children' => (string) $c_6])|noescape}
      {/capture}
      {=og_include('compose/Box.latte', ['class' => 'mt-auto', 'children' => (string) $c_7])|noescape}
    {/capture}
    {=og_include('blocks/article-block.latte', ['p' => ['className' => og_cnv(['rounded bg-card inset-ring inset-ring-border flex flex-col gap-4 p-6']), 'testid' => 'faq-card'], 'children' => og_markup($c_8)])|noescape}
  {/foreach}
{/capture}
{=og_include('compose/Box.latte', ['class' => og_s((og_t(og_eq($v_cards, 'grid4')) ? 'grid grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-4' : 'grid grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-3')), 'attrs' => og_attrs(['data-testid', 'faq']), 'children' => (string) $c_9])|noescape}
